const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const dir = fs.mkdtempSync("/tmp/cfcfg-");
fs.writeFileSync(path.join(dir, "package.json"), JSON.stringify({ name: "cfcfg", private: true, type: "module" }));
fs.writeFileSync(path.join(dir, "cloudflare.config.ts"), "export default { accountId: 123 };\n");
const r = spawnSync(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "deploy", "--dry-run", "--experimental-new-config"], {
  cwd: dir,
  encoding: "utf8",
  timeout: 80000,
  env: { ...process.env, CI: "1", NO_COLOR: "1", FORCE_COLOR: "0", WRANGLER_SEND_METRICS: "false", WRANGLER_HIDE_BANNER: "true" },
});
const out = ((r.stdout || "") + "\n" + (r.stderr || "")).replace(/\x1b\[[0-9;]*m/g, "");
if (!out.includes("Invalid `cloudflare.config.ts`")) broken("no cloudflare.config.ts validation error; status " + r.status + "; output: " + out.slice(0, 800));
if (/\u2022 accountId: /.test(out)) symptom("validation error is printed as '\u2022 accountId: <message>', not in prettifyError format");
if (!/\u2716 .+\n\s*\u2192 at accountId/.test(out)) broken("unexpected validation error format: " + out.slice(0, 800));
console.log("OK: validation error is printed as '\u2716 <message>' followed by '\u2192 at accountId'");

